const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto');
const root=path.resolve(__dirname,'..'),hash=b=>crypto.createHash('sha256').update(b).digest('hex');
function baselineBytes(file){let text=fs.readFileSync(path.join(root,file),'utf8');const m=require('../ROOM-01B_CHANGES.json');for(const p of [...(m.sourcePatches[file]||[])].reverse()){assert.equal(text.split(p.new).length,2,file+' unique ROOM-01B hunk');text=text.replace(p.new,()=>p.old);}return Buffer.from(text,'utf8');}
function baselineText(file){return baselineBytes(file).toString('utf8').replaceAll('\r\n','\n');}
function baselineModule(file){const localModule={exports:{}};Function('module','window','globalThis',baselineText(file))(localModule,undefined,{});return localModule.exports;}
function validatePreservation(){const m=require('../ROOM-01B_CHANGES.json');assert.equal(m.baselineCommit,'573d0e168ebc7de88a55f8589c3d37a7ca404693');assert.equal(m.userContractSha256,'f5b594e1c70d5304081a22bfead32189c15b147a72d04016af576cd88f5e75f2');assert.deepEqual(Object.keys(m.sourcePatches).sort(),['README.md','index.html','map-semantics.js','room-contract.js','room-identification.js','schedule-engine.js','tests/geo02-browser.cjs','tests/room01-browser.cjs','tests/room01-contract.cjs','tests/room01-data.cjs'].sort());for(const [file,h] of Object.entries(m.baselineFiles)){assert.equal(hash(baselineBytes(file)),h.sha256,file+' exact pre-ROOM-01B bytes');}return {protectedFiles:Object.keys(m.baselineFiles).length,changedFiles:Object.keys(m.sourcePatches),geometrySha256:m.baselineFiles['map-data.js'].sha256};}
